  let _mergedAtlasCache = null;
  const _remoteAtlasCache = new Map();

  function getFullBoundaryAtlas() {
    if (_mergedAtlasCache) return _mergedAtlasCache;
    const baseEntries = [
      { name: 'Beirut', code: 'BEY', corridor: 'Beirut', kind: 'Governorate & Capital', aliases: ['Beyrouth', 'Beirut Governorate', 'بيروت'], lat: 33.88918, lng: 35.50469, geojson: BASELINE_POLYGONS['Beirut'].geojson },
      { name: 'South Lebanon', code: 'STH', corridor: 'South', kind: 'Governorate', aliases: ['Jnoub', 'Al Janoub', 'South Governorate', 'الجنوب'], lat: 33.33872, lng: 35.37054, geojson: BASELINE_POLYGONS['Jnoub'].geojson },
      { name: 'Nabatieh', code: 'NAB', corridor: 'Nabatieh', kind: 'City & Governorate', aliases: ['El Nabatieh', 'Nabatiye', 'النبطية'], lat: 33.37896, lng: 35.48699, geojson: BASELINE_POLYGONS['Nabatieh'].geojson },
      { name: 'Dekwaneh', code: 'DKW', corridor: 'Mount Lebanon', kind: 'Municipality', aliases: ['Mkalles', 'Jisr El Bacha', 'الدكوانة'], lat: 33.87618, lng: 35.54635, geojson: BASELINE_POLYGONS['Dekwaneh'].geojson },
      { name: 'Jiyeh', code: 'JYH', corridor: 'Mount Lebanon', kind: 'Coastal Municipality', aliases: ['Al Jiyeh', 'Jiye', 'الجية'], lat: 33.66537, lng: 35.41952, geojson: BASELINE_POLYGONS['Jiyeh'].geojson },
      { name: 'Sibline', code: 'SBL', corridor: 'Mount Lebanon', kind: 'Industrial & Municipal Zone', aliases: ['Iqlim El Kharroub', 'سبلين'], lat: 33.62553, lng: 35.42180, geojson: BASELINE_POLYGONS['Sibline'].geojson },
      { name: 'Borj Hammoud', code: 'BHM', corridor: 'Mount Lebanon', kind: 'Municipality', aliases: ['Bourj Hammoud', 'Dora', 'Dawra', 'برج حمود'], lat: 33.89301, lng: 35.54337, geojson: BASELINE_POLYGONS['Borj Hammoud 2'].geojson },
      { name: 'Aawkar', code: 'AWK', corridor: 'Mount Lebanon', kind: 'Municipality', aliases: ['Awkar', 'عوكر'], lat: 33.93399, lng: 35.60018, geojson: BASELINE_POLYGONS['Aawkar'].geojson },
      { name: 'Halat', code: 'HLT', corridor: 'Mount Lebanon', kind: 'Coastal Municipality', aliases: ['Halate', 'حالات'], lat: 34.08688, lng: 35.66754, geojson: BASELINE_POLYGONS['Halat JV'].geojson }
    ];
    const seen = new Set();
    const out = [];
    baseEntries.concat(MAP_REGION_ATLAS).forEach(it => {
      if (!it || !it.name) return;
      const k = norm(it.name);
      if (seen.has(k)) return;
      seen.add(k);
      out.push(it);
    });
    _mergedAtlasCache = out;
    return out;
  }

  function deriveRegionCode(name, explicitCode) {
    if (explicitCode && String(explicitCode).trim()) {
      return String(explicitCode).trim().toUpperCase().replace(/[^A-Z0-9_]/g, '').slice(0, 8);
    }
    const clean = String(name || '').trim().toUpperCase().replace(/[^A-Z0-9]+/g, ' ').trim();
    if (!clean) return 'REG';
    const parts = clean.split(/\s+/);
    if (parts.length >= 2) {
      return (parts[0].slice(0, 2) + parts[1].slice(0, 2)).slice(0, 6);
    }
    const consonants = clean.replace(/[AEIOU]/g, '');
    return (consonants.length >= 3 ? consonants.slice(0, 3) : clean.slice(0, 4));
  }

  function mapOsmStateToCorridor(rawState, displayName) {
    const s = norm((rawState || '') + ' ' + (displayName || ''));
    if (s.includes('beirut') || s.includes('beyrouth') || s.includes('بيروت')) return 'Beirut';
    if (s.includes('akkar') || s.includes('halba') || s.includes('عكار') || s.includes('حلبا')) return 'Akkar';
    if (s.includes('baalbek') || s.includes('baalbeck') || s.includes('hermel') || s.includes('بعلبك') || s.includes('الهرمل')) return 'Baalbek-Hermel';
    if (s.includes('nabat') || s.includes('marjayoun') || s.includes('marjeyoun') || s.includes('hasbaya') || s.includes('bint jbeil') || s.includes('النبطية') || s.includes('مرجعيون') || s.includes('حاصبيا') || s.includes('بنت جبيل')) return 'Nabatieh';
    if (s.includes('south') || s.includes('jnoub') || s.includes('janoub') || s.includes('sidon') || s.includes('saida') || s.includes('sayda') || s.includes('tyre') || s.includes('sour') || s.includes('jezzine') || s.includes('الجنوب') || s.includes('صيدا') || s.includes('صور') || s.includes('جزين')) return 'South';
    if (s.includes('beqaa') || s.includes('bekaa') || s.includes('zahle') || s.includes('rachaiya') || s.includes('rashaya') || s.includes('chtaura') || s.includes('البقاع') || s.includes('زحلة') || s.includes('راشيا')) return 'Bekaa';
    if (s.includes('north') || s.includes('tripoli') || s.includes('trablous') || s.includes('batroun') || s.includes('zgharta') || s.includes('koura') || s.includes('bcharre') || s.includes('bsharri') || s.includes('miniyeh') || s.includes('danniyeh') || s.includes('chekka') || s.includes('الشمال') || s.includes('طرابلس') || s.includes('البترون') || s.includes('زغرتا') || s.includes('الكورة') || s.includes('بشري')) return 'North';
    if (s.includes('mount lebanon') || s.includes('keserwan') || s.includes('kesrouan') || s.includes('jbeil') || s.includes('byblos') || s.includes('metn') || s.includes('matn') || s.includes('baabda') || s.includes('aley') || s.includes('chouf') || s.includes('shouf') || s.includes('jounieh') || s.includes('جبل لبنان') || s.includes('كسروان') || s.includes('جبيل') || s.includes('المتن') || s.includes('بعبدا') || s.includes('الشوف')) return 'Mount Lebanon';
    const rawTrim = String(rawState || '').trim();
    if (rawTrim) return rawTrim.replace(/\s+Governorate$/i, '').trim();
    return 'Mount Lebanon';
  }

  function corridorLabel(corridorVal) {
    const v = String(corridorVal || '').trim();
    if (!v) return '';
    const map = {
      'Mount Lebanon': 'Mount Lebanon',
      'Beirut': 'Beirut',
      'South': 'South Lebanon',
      'South Lebanon': 'South Lebanon',
      'Nabatieh': 'Nabatieh',
      'Bekaa': 'Bekaa',
      'Baalbek-Hermel': 'Baalbek-Hermel',
      'North': 'North Lebanon',
      'North Lebanon': 'North Lebanon',
      'Akkar': 'Akkar'
    };
    return map[v] || v;
  }

  let _genuineMunicipalPolys = null;
  const _reverseGovCache = new Map();
  let _revGovTimer = null;

  function isSyntheticBboxRing(ring) {
    if (!Array.isArray(ring) || ring.length !== 5) return false;
    const p0 = ring[0], p1 = ring[1], p2 = ring[2], p3 = ring[3];
    return Math.abs(p0[1] - p1[1]) < 1e-6 && Math.abs(p1[0] - p2[0]) < 1e-6 && Math.abs(p2[1] - p3[1]) < 1e-6;
  }

  function getGenuineMunicipalPolys() {
    if (_genuineMunicipalPolys) return _genuineMunicipalPolys;
    const list = [];
    getFullBoundaryAtlas().forEach(it => {
      if (!it || !it.geojson || !it.corridor) return;
      const gj = parseZoneGeoJson(it.geojson);
      if (!gj) return;
      if (gj.type === 'Polygon' && Array.isArray(gj.coordinates) && Array.isArray(gj.coordinates[0])) {
        if (gj.coordinates[0].length < 7 || isSyntheticBboxRing(gj.coordinates[0])) return;
      }
      const area = regionAreaKm2({ zone_type: 'polygon', zone_geojson: gj });
      list.push({ name: it.name, corridor: it.corridor, geojson: gj, areaKm2: area });
    });
    list.sort((a, b) => a.areaKm2 - b.areaKm2);
    _genuineMunicipalPolys = list;
    return list;
  }

  function minDistToRingKm(lat, lng, ring) {
    if (!Array.isArray(ring) || !ring.length) return 999999;
    const cosLat = Math.cos((lat * Math.PI) / 180) || 0.83;
    const kx = 111.32 * cosLat;
    const ky = 110.574;
    let bestSq = Infinity;
    for (let i = 0; i < ring.length; i++) {
      const a = ring[i];
      const b = ring[(i + 1) % ring.length];
      const ax = (Number(a[0]) - lng) * kx, ay = (Number(a[1]) - lat) * ky;
      const bx = (Number(b[0]) - lng) * kx, by = (Number(b[1]) - lat) * ky;
      const dx = bx - ax, dy = by - ay;
      const lenSq = dx * dx + dy * dy;
      let t = lenSq > 1e-12 ? (-(ax * dx + ay * dy) / lenSq) : 0;
      if (t < 0) t = 0;
      else if (t > 1) t = 1;
      const px = ax + t * dx, py = ay + t * dy;
      const dSq = px * px + py * py;
      if (dSq < bestSq) bestSq = dSq;
    }
    return Math.sqrt(bestSq);
  }

  function minDistToGeoJsonKm(lat, lng, gj) {
    if (!gj || !Array.isArray(gj.coordinates)) return 999999;
    if (gj.type === 'Polygon') return minDistToRingKm(lat, lng, gj.coordinates[0]);
    if (gj.type === 'MultiPolygon') {
      let best = 999999;
      for (let i = 0; i < gj.coordinates.length; i++) {
        const poly = gj.coordinates[i];
        if (poly && poly[0]) {
          const d = minDistToRingKm(lat, lng, poly[0]);
          if (d < best) best = d;
        }
      }
      return best;
    }
    return 999999;
  }

  function resolveGovernorateForPoint(lat, lng) {
    const nLat = Number(lat), nLng = Number(lng);
    if (lat == null || lng == null || lat === '' || lng === '' || !Number.isFinite(nLat) || !Number.isFinite(nLng)) {
      return { code: '', label: '', source: 'empty', outsideLebanon: false };
    }
    const muniPolys = getGenuineMunicipalPolys();
    for (let i = 0; i < muniPolys.length; i++) {
      const m = muniPolys[i];
      if (pointInGeoJson(nLat, nLng, m.geojson)) {
        return { code: m.corridor, label: corridorLabel(m.corridor), source: 'municipality', matchedRegion: m.name, outsideLebanon: false };
      }
    }
    for (let i = 0; i < GOVERNORATE_BOUNDARIES.length; i++) {
      const g = GOVERNORATE_BOUNDARIES[i];
      if (pointInGeoJson(nLat, nLng, g.geojson)) {
        return { code: g.code, label: corridorLabel(g.code), source: 'governorate', outsideLebanon: false };
      }
    }
    let bestDist = 999999;
    let bestCode = '';
    for (let i = 0; i < GOVERNORATE_BOUNDARIES.length; i++) {
      const g = GOVERNORATE_BOUNDARIES[i];
      const d = minDistToGeoJsonKm(nLat, nLng, g.geojson);
      if (d < bestDist) {
        bestDist = d;
        bestCode = g.code;
      }
    }
    if (bestCode && bestDist <= 12) {
      return { code: bestCode, label: corridorLabel(bestCode), source: 'coastal_nearest', outsideLebanon: false };
    }
    const cacheKey = `${round2(nLat)},${round2(nLng)}`;
    if (_reverseGovCache.has(cacheKey)) {
      const cached = _reverseGovCache.get(cacheKey);
      return { code: cached, label: corridorLabel(cached), source: 'osm_reverse', outsideLebanon: true };
    }
    return { code: '', label: '', source: 'outside', outsideLebanon: true };
  }

  function maybeReverseGeocodeGovernorate(lat, lng, onResolved) {
    const nLat = Number(lat), nLng = Number(lng);
    if (!Number.isFinite(nLat) || !Number.isFinite(nLng)) return;
    if (navigator.webdriver || window.__MFG_HEADLESS_TEST || typeof window.fetch !== 'function' || (typeof navigator !== 'undefined' && navigator.onLine === false)) return;
    const cacheKey = `${round2(nLat)},${round2(nLng)}`;
    if (_reverseGovCache.has(cacheKey)) {
      if (typeof onResolved === 'function') onResolved(_reverseGovCache.get(cacheKey));
      return;
    }
    clearTimeout(_revGovTimer);
    _revGovTimer = setTimeout(() => {
      fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&zoom=8&lat=${encodeURIComponent(nLat)}&lon=${encodeURIComponent(nLng)}`, {
        headers: { 'Accept-Language': 'en' }
      }).then(r => r.ok ? r.json() : null).then(data => {
        if (!data || !data.address) return;
        const addr = data.address;
        const rawGov = addr.state || addr.region || addr.province || addr.county || addr.country || '';
        if (!rawGov) return;
        const code = (addr.country_code === 'lb' || /lebanon/i.test(addr.country || ''))
          ? mapOsmStateToCorridor(rawGov, data.display_name || '')
          : String(rawGov).replace(/\s+Governorate$/i, '').trim();
        if (code) {
          _reverseGovCache.set(cacheKey, code);
          if (typeof onResolved === 'function') onResolved(code);
        }
      }).catch(() => {});
    }, 240);
  }

  function resolveGovernorateForCircle(cLat, cLng, radiusKm) {
    const centerRes = resolveGovernorateForPoint(cLat, cLng);
    if (!centerRes.code && centerRes.outsideLebanon) return centerRes;
    const rKm = Math.min(4, Math.max(0.2, Number(radiusKm) || 1.5)) * 0.5;
    if (centerRes.source === 'municipality' || centerRes.source === 'governorate' || !(rKm > 0)) {
      return centerRes;
    }
    const votes = new Map();
    const addVote = (code, w) => { if (code) votes.set(code, (votes.get(code) || 0) + w); };
    addVote(centerRes.code, 2.0);
    const dLat = rKm / 110.574;
    const dLng = rKm / (111.32 * (Math.cos((Number(cLat) * Math.PI) / 180) || 0.83));
    [[dLat, 0], [-dLat, 0], [0, dLng], [0, -dLng]].forEach(([oy, ox]) => {
      const pRes = resolveGovernorateForPoint(Number(cLat) + oy, Number(cLng) + ox);
      addVote(pRes.code, 0.75);
    });
    let bestCode = centerRes.code, bestScore = -1;
    votes.forEach((sc, cd) => { if (sc > bestScore) { bestScore = sc; bestCode = cd; } });
    return { code: bestCode, label: corridorLabel(bestCode), source: 'circle', outsideLebanon: !bestCode };
  }

  function computePolyCentroidLngLat(pts) {
    if (!Array.isArray(pts) || !pts.length) return null;
    if (pts.length === 1) return [Number(pts[0][0]), Number(pts[0][1])];
    if (pts.length === 2) return [(Number(pts[0][0]) + Number(pts[1][0])) / 2, (Number(pts[0][1]) + Number(pts[1][1])) / 2];
    let area2 = 0, cx = 0, cy = 0;
    for (let i = 0; i < pts.length; i++) {
      const x0 = Number(pts[i][0]), y0 = Number(pts[i][1]);
      const x1 = Number(pts[(i + 1) % pts.length][0]), y1 = Number(pts[(i + 1) % pts.length][1]);
      const cross = x0 * y1 - x1 * y0;
      area2 += cross;
      cx += (x0 + x1) * cross;
      cy += (y0 + y1) * cross;
    }
    if (Math.abs(area2) > 1e-10) {
      return [cx / (3 * area2), cy / (3 * area2)];
    }
    let sx = 0, sy = 0;
    pts.forEach(p => { sx += Number(p[0]); sy += Number(p[1]); });
    return [sx / pts.length, sy / pts.length];
  }

  function resolveGovernorateForPolygonPoints(pts) {
    if (!Array.isArray(pts) || !pts.length) return { code: '', label: '', source: 'empty', outsideLebanon: false };
    const cleanPts = pts.filter(p => Array.isArray(p) && p.length >= 2 && Number.isFinite(Number(p[0])) && Number.isFinite(Number(p[1])));
    if (!cleanPts.length) return { code: '', label: '', source: 'empty', outsideLebanon: false };
    if (cleanPts.length === 1) return resolveGovernorateForPoint(cleanPts[0][1], cleanPts[0][0]);
    const cent = computePolyCentroidLngLat(cleanPts);
    const centRes = cent ? resolveGovernorateForPoint(cent[1], cent[0]) : { code: '', outsideLebanon: false };
    if (cleanPts.length === 2) {
      const p0 = resolveGovernorateForPoint(cleanPts[0][1], cleanPts[0][0]);
      const p1 = resolveGovernorateForPoint(cleanPts[1][1], cleanPts[1][0]);
      const pick = centRes.code || p0.code || p1.code || '';
      return { code: pick, label: corridorLabel(pick), source: 'polygon_edge', outsideLebanon: Boolean(!pick && centRes.outsideLebanon), sampleLat: cent ? cent[1] : cleanPts[0][1], sampleLng: cent ? cent[0] : cleanPts[0][0] };
    }
    const votes = new Map();
    const addVote = (cd, w) => { if (cd) votes.set(cd, (votes.get(cd) || 0) + w); };
    const closedRing = cleanPts.concat([[cleanPts[0][0], cleanPts[0][1]]]);
    const centInside = cent ? pointInRing(cent[0], cent[1], closedRing) : false;
    if (centRes.code) addVote(centRes.code, centInside ? 1.5 : 0.75);
    const perVertexWeight = 2.0 / cleanPts.length;
    cleanPts.forEach(p => {
      const vr = resolveGovernorateForPoint(p[1], p[0]);
      addVote(vr.code, perVertexWeight);
    });
    let bestCode = centRes.code || '', bestScore = -1;
    votes.forEach((sc, cd) => { if (sc > bestScore) { bestScore = sc; bestCode = cd; } });
    return {
      code: bestCode,
      label: corridorLabel(bestCode),
      source: 'polygon',
      outsideLebanon: Boolean(!bestCode && centRes.outsideLebanon),
      sampleLat: cent ? cent[1] : cleanPts[0][1],
      sampleLng: cent ? cent[0] : cleanPts[0][0]
    };
  }

  function resolveGovernorateForGeoJson(geojson) {
    const gj = parseZoneGeoJson(geojson);
    if (!gj) return { code: '', label: '', source: 'empty', outsideLebanon: false };
    let ring = null;
    if (gj.type === 'Polygon' && Array.isArray(gj.coordinates) && Array.isArray(gj.coordinates[0])) {
      ring = gj.coordinates[0];
    } else if (gj.type === 'MultiPolygon' && Array.isArray(gj.coordinates)) {
      let best = [];
      gj.coordinates.forEach(poly => {
        if (poly && Array.isArray(poly[0]) && poly[0].length > best.length) best = poly[0];
      });
      ring = best;
    }
    if (!ring || !ring.length) return { code: '', label: '', source: 'empty', outsideLebanon: false };
    const open = (ring.length >= 4 && ring[0][0] === ring[ring.length - 1][0] && ring[0][1] === ring[ring.length - 1][1])
      ? ring.slice(0, -1)
      : ring.slice();
    const step = open.length > 24 ? Math.ceil(open.length / 24) : 1;
    const sampled = [];
    for (let i = 0; i < open.length; i += step) sampled.push(open[i]);
    return resolveGovernorateForPolygonPoints(sampled);
  }

  function resolveGovernorate(spec = {}, SEED = null) {
    if (!spec || typeof spec !== 'object') return { code: '', label: '', source: 'empty', outsideLebanon: false };
    const zt = spec.zoneType || spec.zone_type || '';
    if (zt === 'boundary' && spec.name) {
      const hit = findAtlasRegionByName(spec.name, SEED);
      if (hit && hit.corridor) return { code: hit.corridor, label: corridorLabel(hit.corridor), source: 'atlas', outsideLebanon: false };
    }
    if (zt === 'boundary' && spec.corridor) {
      return { code: spec.corridor, label: corridorLabel(spec.corridor), source: 'atlas', outsideLebanon: false };
    }
    if (zt === 'circle') {
      const lat = spec.lat != null ? spec.lat : spec.center_lat;
      const lng = spec.lng != null ? spec.lng : spec.center_lng;
      const rad = spec.radiusKm != null ? spec.radiusKm : spec.radius_km;
      if (lat != null && lng != null && lat !== '' && lng !== '') {
        return resolveGovernorateForCircle(lat, lng, rad);
      }
      return { code: '', label: '', source: 'empty', outsideLebanon: false };
    }
    if (Array.isArray(spec.polyPoints) && spec.polyPoints.length > 0) {
      return resolveGovernorateForPolygonPoints(spec.polyPoints);
    }
    const gj = spec.geojson || spec.zone_geojson;
    if (gj) {
      const gjRes = resolveGovernorateForGeoJson(gj);
      if (gjRes.code || gjRes.outsideLebanon) return gjRes;
    }
    const lat = spec.lat != null ? spec.lat : spec.center_lat;
    const lng = spec.lng != null ? spec.lng : spec.center_lng;
    if (lat != null && lng != null && lat !== '' && lng !== '') {
      return resolveGovernorateForPoint(lat, lng);
    }
    if (spec.name) {
      const hit = findAtlasRegionByName(spec.name, SEED);
      if (hit && hit.corridor) return { code: hit.corridor, label: corridorLabel(hit.corridor), source: 'atlas_name', outsideLebanon: false };
    }
    if (spec.corridor) {
      return { code: spec.corridor, label: corridorLabel(spec.corridor), source: 'stored', outsideLebanon: false };
    }
    return { code: '', label: '', source: 'empty', outsideLebanon: false };
  }

  function enrichAtlasItem(it, SEED) {
    const wtcHub = getCompanyHub('WTC', SEED);
    const wtcKm = (it.lat != null && it.lng != null)
      ? Math.round(roadAdjustedKm(wtcHub.lat, wtcHub.lng, Number(it.lat), Number(it.lng)))
      : null;
    let sitesInside = 0;
    if (SEED && SEED.records && Array.isArray(SEED.records.sites) && it.geojson) {
      SEED.records.sites.forEach(s => {
        if (s && !s.voided && s.latitude != null && s.longitude != null) {
          if (pointInGeoJson(Number(s.latitude), Number(s.longitude), it.geojson)) sitesInside++;
        }
      });
    }
    return Object.assign({}, it, {
      code: deriveRegionCode(it.name, it.code),
      corridorLabel: corridorLabel(it.corridor),
      wtcKm,
      sitesInside
    });
  }

  function findAtlasRegionByName(rawName, SEED) {
    const q = norm(rawName);
    if (!q) return null;
    const atlas = getFullBoundaryAtlas();
    for (let i = 0; i < atlas.length; i++) {
      const it = atlas[i];
      if (norm(it.name) === q) return enrichAtlasItem(it, SEED);
      if (Array.isArray(it.aliases) && it.aliases.some(a => norm(a) === q)) return enrichAtlasItem(it, SEED);
    }
    for (const [, remList] of _remoteAtlasCache.entries()) {
      const hit = (remList || []).find(it => norm(it.name) === q);
      if (hit) return enrichAtlasItem(hit, SEED);
    }
    return null;
  }

  let _nomTimer = null;
  let _nomAbort = null;

  function searchMapRegionBoundaries(query, opts = {}) {
    const { SEED, limit = 9, onRemoteResults } = opts;
    const q = norm(query);
    const atlas = getFullBoundaryAtlas();
    let localHits = [];

    if (!q) {
      const featured = ['Beirut', 'Saida', 'Metn', 'Keserwan', 'Chouf', 'Baabda', 'Aley', 'Tripoli', 'Zahle', 'Tyre', 'Jbeil', 'Nabatieh'];
      featured.forEach(fn => {
        const hit = atlas.find(x => norm(x.name) === norm(fn));
        if (hit) localHits.push(enrichAtlasItem(hit, SEED));
      });
      return localHits.slice(0, limit);
    }

    const scored = [];
    atlas.forEach(it => {
      const n = norm(it.name);
      const aliases = (it.aliases || []).map(norm);
      const corr = norm(it.corridorLabel || corridorLabel(it.corridor));
      let score = 0;
      if (n === q) score = 1000;
      else if (aliases.some(a => a === q)) score = 960;
      else if (n.startsWith(q)) score = 840;
      else if (aliases.some(a => a.startsWith(q))) score = 780;
      else if (n.includes(q)) score = 620;
      else if (aliases.some(a => a.includes(q))) score = 560;
      else if (corr.includes(q)) score = 340;
      if (score > 0) scored.push({ score, item: enrichAtlasItem(it, SEED) });
    });
    scored.sort((a, b) => b.score - a.score || a.item.name.localeCompare(b.item.name));
    localHits = scored.slice(0, limit).map(x => x.item);

    // Merge cached remote Nominatim GeoJSON hits if already fetched for this query
    if (_remoteAtlasCache.has(q)) {
      const cachedRem = _remoteAtlasCache.get(q) || [];
      const seen = new Set(localHits.map(x => norm(x.name)));
      cachedRem.forEach(r => {
        if (!seen.has(norm(r.name))) {
          seen.add(norm(r.name));
          localHits.push(enrichAtlasItem(r, SEED));
        }
      });
      return localHits.slice(0, limit);
    }

    // Live OpenStreetMap Nominatim polygon_geojson=1 search when online (quarantined in headless tests)
    if (q.length >= 2 && typeof onRemoteResults === 'function' && typeof window.fetch === 'function' &&
        !navigator.webdriver && !window.__MFG_HEADLESS_TEST && (typeof navigator === 'undefined' || navigator.onLine !== false)) {
      clearTimeout(_nomTimer);
      _nomTimer = setTimeout(() => {
        if (_nomAbort) { try { _nomAbort.abort(); } catch (_) {} }
        _nomAbort = typeof AbortController === 'function' ? new AbortController() : null;
        const sig = _nomAbort ? _nomAbort.signal : undefined;
        const fetchNom = (qStr) => fetch(
          `https://nominatim.openstreetmap.org/search?format=jsonv2&polygon_geojson=1&addressdetails=1&limit=6&q=${encodeURIComponent(qStr)}`,
          { signal: sig, headers: { 'Accept-Language': 'en' } }
        ).then(r => r.ok ? r.json() : []);

        fetchNom(query + ', Lebanon').then(arr => {
          if (Array.isArray(arr) && arr.length > 0) return arr;
          return fetchNom(query);
        }).then(arr => {
          if (!Array.isArray(arr)) return;
          const remItems = [];
          arr.forEach(row => {
            if (!row || row.lat == null || row.lon == null) return;
            const rawName = String(row.name || (row.display_name || '').split(',')[0] || '').trim();
            if (!rawName) return;
            let gj = row.geojson && (row.geojson.type === 'Polygon' || row.geojson.type === 'MultiPolygon') ? row.geojson : null;
            if (!gj && Array.isArray(row.boundingbox) && row.boundingbox.length === 4) {
              const s = round5(parseFloat(row.boundingbox[0])), n = round5(parseFloat(row.boundingbox[1]));
              const w = round5(parseFloat(row.boundingbox[2])), e = round5(parseFloat(row.boundingbox[3]));
              if (Math.abs(n - s) > 0.0015 && Math.abs(e - w) > 0.0015) {
                gj = { type: 'Polygon', coordinates: [[[w, s], [e, s], [e, n], [w, n], [w, s]]] };
              }
            }
            if (!gj) return;
            const addr = row.address || {};
            const corr = mapOsmStateToCorridor(addr.state || addr.county || '', row.display_name || '');
            remItems.push({
              name: rawName,
              code: deriveRegionCode(rawName),
              corridor: corr,
              kind: row.addresstype ? (row.addresstype.charAt(0).toUpperCase() + row.addresstype.slice(1)) : 'Map Boundary',
              aliases: [],
              lat: round5(parseFloat(row.lat)),
              lng: round5(parseFloat(row.lon)),
              geojson: gj,
              isLiveOsm: true
            });
          });
          _remoteAtlasCache.set(q, remItems);
          const merged = localHits.slice();
          const seen = new Set(merged.map(x => norm(x.name)));
          remItems.forEach(r => {
            if (!seen.has(norm(r.name))) {
              seen.add(norm(r.name));
              merged.push(enrichAtlasItem(r, SEED));
            }
          });
          onRemoteResults(merged.slice(0, limit));
        }).catch(() => {});
      }, 260);
    }

    return localHits.slice(0, limit);
  }

  function extractEditablePolyRing(geojson, maxVertices = 22) {
    const gj = parseZoneGeoJson(geojson);
    if (!gj) return [];
    let ring = null;
    if (gj.type === 'Polygon' && Array.isArray(gj.coordinates) && Array.isArray(gj.coordinates[0])) {
      ring = gj.coordinates[0];
    } else if (gj.type === 'MultiPolygon' && Array.isArray(gj.coordinates)) {
      let best = [];
      gj.coordinates.forEach(poly => {
        if (poly && Array.isArray(poly[0]) && poly[0].length > best.length) best = poly[0];
      });
      ring = best;
    }
    if (!ring || ring.length < 3) return [];
    let open = ring.slice();
    if (open.length >= 4 && open[0][0] === open[open.length - 1][0] && open[0][1] === open[open.length - 1][1]) {
      open = open.slice(0, -1);
    }
    if (open.length <= maxVertices) {
      return open.map(p => [round5(p[0]), round5(p[1])]);
    }
    const step = open.length / maxVertices;
    const sampled = [];
    for (let i = 0; i < maxVertices; i++) {
      const pt = open[Math.min(open.length - 1, Math.floor(i * step))];
      sampled.push([round5(pt[0]), round5(pt[1])]);
    }
    return sampled;
  }

  function stripLeafletTitles(rootEl) {
    if (!rootEl || !rootEl.querySelectorAll) return;
    rootEl.querySelectorAll('[title]').forEach(el => {
      const t = el.getAttribute('title');
      if (t && !el.getAttribute('aria-label')) el.setAttribute('aria-label', t);
      el.removeAttribute('title');
    });
  }

  const _placeMenuClosers = new Set();
  function closeAllGeoPlaceMenus() {
    Array.from(_placeMenuClosers).forEach(fn => {
      try { fn(); } catch (_) {}
    });
  }

  function attachMapRegionSearchInput(inputEl, opts = {}) {
    if (!inputEl || inputEl.dataset.geoPlaceSearchWired === '1') return null;
    inputEl.dataset.geoPlaceSearchWired = '1';
    const { SEED, onSelectRegion, showPopularOnClick = true, decorateWithIcon = true } = opts;

    let wrap = inputEl.closest('.geo-place-search-wrap');
    if (!wrap) {
      wrap = document.createElement('div');
      wrap.className = 'geo-place-search-wrap' + (decorateWithIcon ? '' : ' is-plain-input');
      inputEl.parentNode.insertBefore(wrap, inputEl);
      wrap.appendChild(inputEl);
    }
    if (decorateWithIcon) {
      inputEl.classList.add('geo-place-inp');
      const ico = document.createElement('span');
      ico.className = 'geo-place-search-ico';
      ico.innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><line x1="20" y1="20" x2="16.2" y2="16.2"/></svg>';
      wrap.insertBefore(ico, inputEl);
    }

    const clearBtn = document.createElement('button');
    clearBtn.type = 'button';
    clearBtn.className = 'geo-place-clear-btn';
    clearBtn.setAttribute('aria-label', 'Clear search');
    clearBtn.textContent = '×';
    clearBtn.hidden = !inputEl.value;
    wrap.appendChild(clearBtn);

    const menu = document.createElement('div');
    menu.className = 'geo-place-menu';
    menu.setAttribute('role', 'listbox');
    menu.hidden = true;
    wrap.appendChild(menu);

    let items = [];
    let activeIdx = -1;
    let blurTimer = null;

    const closeMenu = () => {
      menu.hidden = true;
      wrap.classList.remove('open');
      activeIdx = -1;
    };
    const trackedClose = () => {
      closeMenu();
      if (!inputEl.isConnected) _placeMenuClosers.delete(trackedClose);
    };
    _placeMenuClosers.add(trackedClose);

    const syncClear = () => {
      clearBtn.hidden = !String(inputEl.value || '').trim();
    };

    const pickItem = (idx) => {
      const it = items[idx];
      if (!it) return;
      closeMenu();
      syncClear();
      if (typeof onSelectRegion === 'function') onSelectRegion(it);
    };

    const renderList = (list, queryText) => {
      items = list || [];
      if (typeof opts.shouldOpen === 'function' && !opts.shouldOpen()) {
        closeMenu();
        return;
      }
      if (!items.length) {
        if (String(queryText || '').trim().length >= 2) {
          menu.innerHTML = `<div class="geo-place-menu-hdr"><span>Map Boundary Search</span><span>0 exact matches</span></div><div style="padding:7px 9px;font-size:11.5px;color:var(--muted)">No pre-mapped boundary for "${esc(queryText)}". Switch Search Zone Shape to Circle or Custom Polygon to outline it on the map.</div>`;
          menu.hidden = false;
          wrap.classList.add('open');
        } else {
          closeMenu();
        }
        return;
      }
      activeIdx = String(queryText || '').trim() ? 0 : -1;
      const hdrLeft = String(queryText || '').trim() ? `Matching Map Regions (${items.length})` : 'Popular Lebanon Map Regions';
      menu.innerHTML = `<div class="geo-place-menu-hdr"><span>${esc(hdrLeft)}</span><span>Click to load boundary</span></div>` +
        items.map((it, idx) => `
          <button type="button" class="geo-place-item${idx === activeIdx ? ' active' : ''}" role="option" data-geo-place-idx="${idx}">
            <span class="geo-place-item-main">
              <span class="geo-place-item-title">${esc(it.name)}</span>
              <span class="geo-place-item-sub">${esc(it.kind || 'Region')} · ${esc(it.corridorLabel || it.corridor || 'Lebanon')}${it.sitesInside > 0 ? ` · ${it.sitesInside} ${it.sitesInside === 1 ? 'Site' : 'Sites'} inside` : ''}</span>
            </span>
            <span class="geo-place-item-badges">
              ${it.wtcKm != null ? `<span class="geo-place-badge is-km">~${it.wtcKm} km</span>` : ''}
              <span class="geo-place-badge">Map Boundary</span>
            </span>
          </button>
        `).join('');
      document.querySelectorAll('.pa-select-wrap.open, .pa-suggest-wrap.open, .geo-place-search-wrap.open').forEach(ow => {
        if (ow === wrap) return;
        ow.classList.remove('open');
        const om = ow.querySelector('.pa-select-menu, .pa-suggest-menu, .geo-place-menu');
        if (om) om.hidden = true;
      });
      menu.hidden = false;
      wrap.classList.add('open');
      menu.querySelectorAll('[data-geo-place-idx]').forEach(btn => {
        let handled = false;
        const onPick = ev => {
          ev.preventDefault();
          ev.stopPropagation();
          if (handled) return;
          handled = true;
          clearTimeout(blurTimer);
          pickItem(Number(btn.getAttribute('data-geo-place-idx')));
        };
        btn.addEventListener('mousedown', onPick);
        btn.addEventListener('click', onPick);
      });
    };

    const runQuery = (allowEmpty) => {
      syncClear();
      const q = String(inputEl.value || '').trim();
      if (!q && !allowEmpty) {
        closeMenu();
        return;
      }
      const res = searchMapRegionBoundaries(q, {
        SEED,
        onRemoteResults: (merged) => {
          if (document.activeElement === inputEl && norm(inputEl.value) === norm(q)) {
            renderList(merged, q);
          }
        }
      });
      renderList(res, q);
    };

    inputEl.addEventListener('input', () => runQuery(showPopularOnClick));
    inputEl.addEventListener('mousedown', () => {
      if (showPopularOnClick && menu.hidden) {
        setTimeout(() => { if (document.activeElement === inputEl) runQuery(true); }, 10);
      }
    });
    inputEl.addEventListener('keydown', ev => {
      if (menu.hidden || !items.length) {
        if (ev.key === 'ArrowDown' && showPopularOnClick) {
          ev.preventDefault();
          runQuery(true);
        }
        return;
      }
      if (ev.key === 'ArrowDown') {
        ev.preventDefault();
        activeIdx = (activeIdx + 1) % items.length;
        menu.querySelectorAll('.geo-place-item').forEach((b, i) => b.classList.toggle('active', i === activeIdx));
      } else if (ev.key === 'ArrowUp') {
        ev.preventDefault();
        activeIdx = (activeIdx - 1 + items.length) % items.length;
        menu.querySelectorAll('.geo-place-item').forEach((b, i) => b.classList.toggle('active', i === activeIdx));
      } else if (ev.key === 'Enter') {
        if (activeIdx >= 0 && items[activeIdx]) {
          ev.preventDefault();
          ev.stopPropagation();
          pickItem(activeIdx);
        } else {
          closeMenu();
        }
      } else if (ev.key === 'Escape') {
        ev.preventDefault();
        ev.stopPropagation();
        closeMenu();
      } else if (ev.key === 'Tab') {
        closeMenu();
      }
    });
    inputEl.addEventListener('blur', () => {
      clearTimeout(blurTimer);
      blurTimer = setTimeout(() => {
        if (!wrap.contains(document.activeElement)) closeMenu();
      }, 140);
    });
    const onClearClick = ev => {
      ev.preventDefault();
      ev.stopPropagation();
      inputEl.value = '';
      syncClear();
      if (typeof opts.onClear === 'function') opts.onClear();
      inputEl.focus({ preventScroll: true });
      if (showPopularOnClick) runQuery(true);
    };
    clearBtn.addEventListener('mousedown', onClearClick);
    clearBtn.addEventListener('click', onClearClick);

    const onOutsideEvt = ev => {
      if (!wrap.isConnected) {
        document.removeEventListener('mousedown', onOutsideEvt, true);
        document.removeEventListener('click', onOutsideEvt, true);
        return;
      }
      if (!menu.hidden && !wrap.contains(ev.target)) {
        closeMenu();
      }
    };
    document.addEventListener('mousedown', onOutsideEvt, true);
    document.addEventListener('click', onOutsideEvt, true);

    return { closeMenu, syncClear, runQuery };
  }

  function makeVertexDivIcon(L, isFirst, canClose) {
    const cls = `geo-vertex-dot${isFirst ? ' is-first' : ''}${isFirst && canClose ? ' can-close' : ''}`;
    const sz = isFirst ? 16 : 14;
    return L.divIcon({
      className: 'geo-vertex-icon',
      iconSize: [sz, sz],
      iconAnchor: [sz / 2, sz / 2],
      html: `<div class="${cls}"></div>`
    });
  }

  function makeMidpointDivIcon(L) {
    return L.divIcon({
      className: 'geo-midpoint-icon',
      iconSize: [11, 11],
      iconAnchor: [5.5, 5.5],
      html: '<div class="geo-midpoint-dot"></div>'
    });
  }

  const norm = s => String(s || '').trim().toLowerCase().replace(/\s+/g, ' ');
  const round1 = n => Math.round((Number(n) || 0) * 10) / 10;
  const round2 = n => Math.round((Number(n) || 0) * 100) / 100;
  const round5 = n => Math.round((Number(n) || 0) * 100000) / 100000;
  const esc = s => String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

  function loadStoredConfig() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed && typeof parsed === 'object') return parsed;
      }
    } catch (_) {}
    return { companyHubs: {}, regions: {}, sites: {}, pairKmOverrides: {}, routeKmCache: {}, updatedAt: '' };
  }

  let GEO_STORE = loadStoredConfig();
  if (!GEO_STORE.companyHubs) GEO_STORE.companyHubs = {};
  if (!GEO_STORE.regions) GEO_STORE.regions = {};
  if (!GEO_STORE.sites) GEO_STORE.sites = {};
  if (!GEO_STORE.pairKmOverrides) GEO_STORE.pairKmOverrides = {};
  if (!GEO_STORE.routeKmCache) GEO_STORE.routeKmCache = {};

  function saveStoredConfig(pushServer = true) {
    GEO_STORE.updatedAt = new Date().toISOString();
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(GEO_STORE));
    } catch (_) {}
    if (pushServer && typeof window.fetch === 'function' && !navigator.webdriver && !window.__MFG_HEADLESS_TEST) {
      try {
        fetch('./api/geo_config', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ config: exportGeoConfig() })
        }).catch(() => {});
      } catch (_) {}
    }
    if (typeof window.__mfgScheduleCloudPush === 'function') {
      try { window.__mfgScheduleCloudPush(); } catch (_) {}
    }
  }

  function exportGeoConfig() {
    return {
      companyHubs: GEO_STORE.companyHubs || {},
      regions: GEO_STORE.regions || {},
      sites: GEO_STORE.sites || {},
      pairKmOverrides: GEO_STORE.pairKmOverrides || {},
      updatedAt: GEO_STORE.updatedAt || ''
    };
  }

  function importGeoConfig(incoming) {
    if (!incoming || typeof incoming !== 'object') return false;
    let changed = false;
    ['companyHubs', 'regions', 'sites', 'pairKmOverrides'].forEach(bucket => {
      const src = incoming[bucket];
      if (!src || typeof src !== 'object') return;
      if (!GEO_STORE[bucket]) GEO_STORE[bucket] = {};
      Object.keys(src).forEach(k => {
        const cur = GEO_STORE[bucket][k];
        const nxt = src[k];
        if (!nxt) return;
        const curTs = (cur && cur.updated_at) || '';
        const nxtTs = (nxt && nxt.updated_at) || incoming.updatedAt || '';
        if (!cur || !curTs || nxtTs >= curTs) {
          GEO_STORE[bucket][k] = nxt;
          changed = true;
        }
      });
    });
    if (changed) saveStoredConfig(false);
    return changed;
  }

  // ==================== GEOMETRY & SPATIAL CONTAINMENT ENGINE ====================
  function haversineKm(lat1, lng1, lat2, lng2) {
    const R = 6371.0088;
    const toRad = d => (d * Math.PI) / 180;
    const dLat = toRad(lat2 - lat1);
    const dLng = toRad(lng2 - lng1);
    const a = Math.sin(dLat / 2) ** 2 +
      Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
    return 2 * R * Math.asin(Math.min(1, Math.sqrt(a)));
  }

  function pointInCircle(lat, lng, cLat, cLng, radiusKm) {
    if (!(radiusKm > 0)) return false;
    return haversineKm(lat, lng, cLat, cLng) <= Number(radiusKm) + 0.015;
  }

  function pointInRing(lng, lat, ring) {
    let inside = false;
    for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
      const xi = Number(ring[i][0]), yi = Number(ring[i][1]);
      const xj = Number(ring[j][0]), yj = Number(ring[j][1]);
      const intersect = ((yi > lat) !== (yj > lat)) &&
        (lng < ((xj - xi) * (lat - yi)) / ((yj - yi) || 1e-12) + xi);
      if (intersect) inside = !inside;
    }
    return inside;
  }

  function pointInGeoJson(lat, lng, gj) {
    if (!gj || !gj.type || !Array.isArray(gj.coordinates)) return false;
    if (gj.type === 'Polygon') {
      const rings = gj.coordinates;
      if (!rings.length || !pointInRing(lng, lat, rings[0])) return false;
      for (let h = 1; h < rings.length; h++) {
        if (pointInRing(lng, lat, rings[h])) return false;
      }
      return true;
    }
    if (gj.type === 'MultiPolygon') {
      for (let p = 0; p < gj.coordinates.length; p++) {
        const rings = gj.coordinates[p];
        if (!rings || !rings.length) continue;
        if (pointInRing(lng, lat, rings[0])) {
          let inHole = false;
          for (let h = 1; h < rings.length; h++) {
            if (pointInRing(lng, lat, rings[h])) { inHole = true; break; }
          }
          if (!inHole) return true;
        }
      }
    }
    return false;
  }

  function approxRingAreaKm2(ring) {
    if (!Array.isArray(ring) || ring.length < 3) return 999999;
    let minLng = 999, maxLng = -999, minLat = 999, maxLat = -999;
    ring.forEach(pt => {
      if (pt[0] < minLng) minLng = pt[0];
      if (pt[0] > maxLng) maxLng = pt[0];
      if (pt[1] < minLat) minLat = pt[1];
      if (pt[1] > maxLat) maxLat = pt[1];
    });
    const w = haversineKm((minLat + maxLat) / 2, minLng, (minLat + maxLat) / 2, maxLng);
    const h = haversineKm(minLat, (minLng + maxLng) / 2, maxLat, (minLng + maxLng) / 2);
    return Math.max(0.05, w * h * 0.72);
  }

  function regionAreaKm2(reg) {
    if (!reg) return 999999;
    if (reg.zone_type === 'circle' && Number(reg.radius_km) > 0) {
      return Math.PI * Number(reg.radius_km) * Number(reg.radius_km);
    }
    const gj = parseZoneGeoJson(reg.zone_geojson);
    if (gj) {
      if (gj.type === 'Polygon' && gj.coordinates[0]) return approxRingAreaKm2(gj.coordinates[0]);
      if (gj.type === 'MultiPolygon') {
        return gj.coordinates.reduce((sum, poly) => sum + (poly && poly[0] ? approxRingAreaKm2(poly[0]) : 0), 0);
      }
    }
    return 999999;
  }

  function parseZoneGeoJson(val) {
    if (!val) return null;
    if (typeof val === 'object') {
      if (val.type === 'FeatureCollection' && val.features && val.features[0]) return val.features[0].geometry;
      if (val.type === 'Feature') return val.geometry;
      return val;
    }
    if (typeof val === 'string') {
      try {
        return parseZoneGeoJson(JSON.parse(val));
      } catch (_) { return null; }
    }
    return null;
  }

  function isPointInRegion(lat, lng, reg) {
    if (!reg || lat == null || lng == null) return false;
    const nLat = Number(lat), nLng = Number(lng);
    if (!Number.isFinite(nLat) || !Number.isFinite(nLng)) return false;
    if (reg.zone_type === 'circle' && reg.center_lat != null && reg.center_lng != null && Number(reg.radius_km) > 0) {
      return pointInCircle(nLat, nLng, Number(reg.center_lat), Number(reg.center_lng), Number(reg.radius_km));
    }
    const gj = parseZoneGeoJson(reg.zone_geojson);
    if (gj) return pointInGeoJson(nLat, nLng, gj);
    return false;
  }

  function findContainingRegion(lat, lng, SEED) {
    const regions = ((SEED && SEED.records && SEED.records.regions) || []);
    const matches = [];
    const seen = new Set();
    for (let i = 0; i < regions.length; i++) {
      const r = regions[i];
      if (!r || r.voided) continue;
      if (isPointInRegion(lat, lng, r)) {
        const areaKm2 = regionAreaKm2(r);
        matches.push({ region: r.name, areaKm2, tier: areaKm2 < 180 ? 0 : 2, row: r });
        seen.add(norm(r.name));
      }
    }
    const atlas = getFullBoundaryAtlas();
    for (let i = 0; i < atlas.length; i++) {
      const a = atlas[i];
      const nk = norm(a.label || a.key);
      if (!nk || seen.has(nk)) continue;
      const syntheticReg = {
        name: a.label,
        zone_type: a.zone_type || (a.poly ? 'boundary' : 'circle'),
        center_lat: a.lat,
        center_lng: a.lng,
        radius_km: a.radius_km || 0,
        zone_geojson: a.poly ? polyFromPairs(a.poly) : null
      };
      if (isPointInRegion(lat, lng, syntheticReg)) {
        const areaKm2 = regionAreaKm2(syntheticReg);
        matches.push({ region: a.label, areaKm2, tier: areaKm2 < 350 ? 1 : 2, row: syntheticReg });
        seen.add(nk);
      }
    }
    matches.sort((a, b) => (a.tier - b.tier) || (a.areaKm2 - b.areaKm2));
    return {
      best: matches[0] ? matches[0].region : '',
      name: matches[0] ? matches[0].region : '',
      matches: matches.map(m => m.region)
    };
  }

